// ─── Helpers ───────────────────────────────────────────────────────
const fmt = n => Number(n||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const today = () => new Date().toISOString().split("T")[0];
const fmtDate = iso => { const [,m,d]=iso.split("-"); return `${d}/${m}`; };
const monthName = m => ["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"][m];
const fullMonth = m => ["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"][m];
const getDays = (y,m) => { const d=[],dt=new Date(y,m,1); while(dt.getMonth()===m){d.push(dt.toISOString().split("T")[0]);dt.setDate(dt.getDate()+1);} return d; };
const getQ = (y,m) => { const all=getDays(y,m); return {q1:all.filter(d=>new Date(d).getDate()<=15),q2:all.filter(d=>new Date(d).getDate()>15)}; };
const uid = () => Math.random().toString(36).slice(2,10);
const getAtt = (data,eid,date) => { const v=data.attendance?.[eid]?.[date]; if(!v)return null; return typeof v==="string"?{status:v,ot:0,note:""}:v; };
const attStatus = (data,eid,date) => getAtt(data,eid,date)?.status || null;
const fmtCPF = v => v.replace(/\D/g,"").replace(/(\d{3})(\d{3})(\d{3})(\d{2})/,"$1.$2.$3-$4").slice(0,14);
const fmtPhone = v => v.replace(/\D/g,"").replace(/(\d{2})(\d{5})(\d{4})/,"($1) $2-$3").slice(0,15);

// ─── Storage (Supabase) ────────────────────────────────────────────
const DEFAULT = () => ({
  userName: "",
  config: {
    companyName: "ArcD Obras",
    productName: "Gestão de Equipes",
    hrEmail: "",
    hrName: "",
    cnpj: ""
  },
  obras: [
    { id: uid(), name: "Obra 1", address: "", engineer: "", startDate: "", status: "active" },
    { id: uid(), name: "Obra 2", address: "", engineer: "", startDate: "", status: "active" },
  ],
  employees: [],
  attendance: {},
  advances: [],
  dailyCheckDate: "",
  changeLog: [],
});
const normalizeData = (incoming) => {
  const base = DEFAULT();
  const d = incoming || {};

  return {
    ...base,
    ...d,
    config: {
      ...base.config,
      ...(d.config || {}),
    },
    obras: Array.isArray(d.obras) ? d.obras : base.obras,
    employees: Array.isArray(d.employees)
      ? d.employees.map(e => ({
          id: e.id || uid(),
          name: e.name || "",
          role: e.role || "",
          cpf: e.cpf || "",
          phone: e.phone || "",
          pixKey: e.pixKey || "",
          dailyRate: Number(e.dailyRate || 0),
          vtDaily: Number(e.vtDaily || 0),
          vrDaily: Number(e.vrDaily || 0),
          obra: e.obra || "",
          active: e.active !== false,
          startDate: e.startDate || "",
          endDate: e.endDate || "",
          terminationReason: e.terminationReason || "",
          lastObra: e.lastObra || "",
        }))
      : [],
    attendance: d.attendance || {},
    advances: Array.isArray(d.advances) ? d.advances : [],
    dailyCheckDate: d.dailyCheckDate || "",
    changeLog: Array.isArray(d.changeLog) ? d.changeLog : [],
  };
};

const isDailyCheckPending = (data, date = today()) => {
  const isToday = date === today();
  const hasActiveEmployees = (data.employees || []).some(e => e.active !== false);

  return isToday && hasActiveEmployees && data.dailyCheckDate !== today();
};

const loadData = async () => {
  try {
    const d = await supabaseLoad();
    return normalizeData(d || DEFAULT());
  } catch {
    return normalizeData(DEFAULT());
  }
};

const saveData = async (d) => {
  try {
    await supabaseSave(d);
  } catch {}
};

