// TELA DE NOME — sem login, apenas pede o nome
// ═══════════════════════════════════════════════════════════════════
function NameScreen({onEnter}){
  const [nome,setNome]=useState("");
  const [erro,setErro]=useState("");

  const entrar=()=>{
    if(!nome.trim()){setErro("Por favor, insira seu nome.");return;}
    onEnter(nome.trim());
  };

  return(
    <div className="animUp" style={{
      minHeight:"100vh",background:C.bg,display:"flex",flexDirection:"column",
      alignItems:"center",justifyContent:"center",padding:24,
      backgroundImage:`radial-gradient(circle at 50% 0%, ${C.yellow}08 0%, transparent 60%)`,
    }}>
      <style>{G}</style>

      <div style={{marginBottom:32}}>
        <ArcedLogo size={100}/>
      </div>

      <div style={{width:"100%",maxWidth:360}}>
        <div style={{textAlign:"center",marginBottom:32}}>
          <h1 style={{fontFamily:"'Bebas Neue'",fontSize:26,color:C.yellow,letterSpacing:6,textTransform:"uppercase",marginBottom:4}}>
            ArcD Construtech
          </h1>
          <p style={{fontSize:12,color:C.muted,letterSpacing:1}}>Gestão de equipe em obras</p>
          <div style={{height:1,background:`linear-gradient(90deg,transparent,${C.yellow},transparent)`,marginTop:12}}/>
        </div>

        <div style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${C.yellow}`,padding:28,display:"flex",flexDirection:"column",gap:18}}>
          <div style={{textAlign:"center",marginBottom:4}}>
            <p style={{fontSize:15,color:C.text,fontWeight:600}}>Bem-vindo!</p>
            <p style={{fontSize:13,color:C.muted,marginTop:4}}>Qual é o seu nome?</p>
          </div>

          <Inp
            label="Seu nome"
            value={nome}
            onChange={v=>{setNome(v);setErro("");}}
            placeholder="Ex.: João Silva"
          />

          {erro&&<p style={{fontSize:13,color:C.red,fontWeight:600}}>⚠️ {erro}</p>}

          <button onClick={entrar} style={{
            background:C.yellow,color:C.bg,border:"none",padding:"14px",
            fontFamily:"'Bebas Neue'",fontSize:20,letterSpacing:3,cursor:"pointer",
            textTransform:"uppercase",display:"flex",alignItems:"center",justifyContent:"center",gap:10,
            marginTop:4,
          }}
            onKeyDown={e=>e.key==="Enter"&&entrar()}
          >
            <Ic n="check" s={18} style={{color:C.bg}}/> ENTRAR
          </button>
        </div>

        <p style={{textAlign:"center",fontSize:11,color:C.muted,marginTop:20}}>
          ArcD Construtora · Sistema de Gestão de Ponto
        </p>
      </div>
    </div>
  );
}

