// MAIN APP
// ═══════════════════════════════════════════════════════════════════
export default function App(){
  const [data,setData]=useState(null);
  const [tab,setTab]=useState("dash");
  const [loading,setLoading]=useState(true);
  const [toast,setToast]=useState(null);
  const [aiOpen,setAiOpen]=useState(false);
  const [loggedIn,setLoggedIn]=useState(false);
  const [showDailyCheck,setShowDailyCheck]=useState(false);

  useEffect(()=>{loadData().then(d=>{
    setData(d);
    setLoading(false);
    // Se já tem nome salvo, entra direto
    if(d.userName && d.userName.trim()) setLoggedIn(true);
  });},[]);

  const update = useCallback(async nd=>{setData(nd);await saveData(nd);},[]);
  const showToast = useCallback((msg,type="success")=>{ setToast({msg,type}); setTimeout(()=>setToast(null),3200); },[]);

  const handleEnterName=async(nome)=>{
    const nd={...data,userName:nome};
    await update(nd);
    setLoggedIn(true);
  };

  const handleLogout=()=>{ setLoggedIn(false); setTab("dash"); };

  if(loading) return(
    <div style={{display:"flex",alignItems:"center",justifyContent:"center",height:"100vh",background:C.bg,flexDirection:"column",gap:20}}>
      <style>{G}</style>
      <ArcedLogo size={70}/>
      <Spinner/>
    </div>
  );

  if(!loggedIn) return <NameScreen onEnter={handleEnterName}/>

  const TABS=[
    {id:"dash",n:"home",l:"Início"},
    {id:"obras",n:"building",l:"Obras"},
    {id:"equipe",n:"users",l:"Equipe"},
    {id:"ponto",n:"clock",l:"Ponto"},
    {id:"folha",n:"dollar",l:"Folha"},
    {id:"relat",n:"chart",l:"Relatórios"},
    {id:"config",n:"settings",l:"Config"},
  ];

  const props={data,update,showToast};

  return(
    <div style={{background:C.bg,minHeight:"100vh",maxWidth:480,margin:"0 auto",position:"relative"}}>
      <style>{G}</style>

      {/* Header */}
      <div style={{background:C.surface,borderBottom:`1px solid ${C.border}`,padding:"10px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",position:"sticky",top:0,zIndex:50}}>
        <div style={{display:"flex",alignItems:"center",gap:12}}>
          <ArcedLogoSmall size={38}/>
          <div>
            <p style={{fontFamily:"'Bebas Neue'",fontSize:13,color:C.yellow,letterSpacing:3,lineHeight:1}}>{data.config.companyName||"ArcD"}</p>
            <p style={{fontSize:10,color:C.muted,letterSpacing:.5}}>{data.userName?" Olá, "+data.userName:"Sistema de Ponto PRO"}</p>
          </div>
        </div>
        <div style={{display:"flex",gap:8}}>
          <button onClick={()=>setAiOpen(true)} style={{background:`linear-gradient(135deg,${C.yellow},${C.yellowD})`,border:"none",borderRadius:0,padding:"7px 12px",cursor:"pointer",display:"flex",alignItems:"center",gap:5,color:C.bg,fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:13,letterSpacing:.5}}>
            <Ic n="bot" s={15}/>IA
          </button>
          <button onClick={handleLogout} style={{background:"none",border:`1px solid ${C.border}`,padding:"7px 10px",cursor:"pointer",display:"flex",alignItems:"center",gap:4,color:C.muted,borderRadius:0}} title="Sair">
            <Ic n="logout" s={15}/>
          </button>
        </div>
      </div>

      {/* Tab bar */}
      <div style={{background:C.surface,borderBottom:`1px solid ${C.border}`,display:"flex",overflowX:"auto",scrollbarWidth:"none",WebkitOverflowScrolling:"touch"}}>
        {TABS.map(t=>(
          <button key={t.id} onClick={()=>setTab(t.id)} style={{
            flex:"0 0 auto",padding:"10px 14px",background:"none",border:"none",cursor:"pointer",
            display:"flex",flexDirection:"column",alignItems:"center",gap:2,
            color:tab===t.id?C.yellow:C.muted,transition:"color .15s",
            borderBottom:tab===t.id?`2px solid ${C.yellow}`:"2px solid transparent",
          }}>
            <Ic n={t.n} s={18}/>
            <span style={{fontSize:9,fontWeight:700,fontFamily:"'Barlow Condensed'",letterSpacing:.7,textTransform:"uppercase"}}>{t.l}</span>
          </button>
        ))}
      </div>

      {/* Content */}
      <div style={{padding:"14px 14px 30px"}}>
        {tab==="dash"   && <Dashboard {...props} onTab={setTab} onDailyCheck={()=>setShowDailyCheck(true)}/>}
        {tab==="obras"  && <Obras {...props}/>}
        {tab==="equipe" && <Equipe {...props}/>}
        {tab==="ponto"  && <Ponto {...props} onDailyCheck={()=>setShowDailyCheck(true)}/>}
        {tab==="folha"  && <Folha {...props}/>}
        {tab==="relat"  && <Relatorios {...props}/>}
        {tab==="config" && <Config {...props} onLogout={handleLogout}/>}
      </div>

      <ToastCtx toast={toast}/>
      {aiOpen && <AIAssistant data={data} onClose={()=>setAiOpen(false)}/>}
      {showDailyCheck && <DailyCheckModal data={data} update={update} showToast={showToast} onClose={()=>setShowDailyCheck(false)}/>}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// DASHBOARD
// ═══════════════════════════════════════════════════════════════════
function Dashboard({data,onTab,onDailyCheck}){
  const now=new Date(), y=now.getFullYear(), m=now.getMonth(), d=now.getDate();
  const {q1,q2}=getQ(y,m);
  const qDays=d<=15?q1:q2;
  const t=today();
  const checkPending=data.employees.filter(e=>e.active!==false).length>0 && data.dailyCheckDate!==t;

  const activeEmps=data.employees.filter(e=>e.active!==false);
  const presentes=activeEmps.filter(e=>attStatus(data,e.id,t)==="P").length;
  const faltas=activeEmps.filter(e=>attStatus(data,e.id,t)==="F").length;
  const meiodia=activeEmps.filter(e=>attStatus(data,e.id,t)==="M").length;
  const semReg=activeEmps.length-presentes-faltas-meiodia;

  let qTotal=0;
  activeEmps.forEach(e=>{ qDays.forEach(dd=>{ const s=attStatus(data,e.id,dd); if(s==="P")qTotal+=e.dailyRate||0; else if(s==="M")qTotal+=(e.dailyRate||0)*.5; }); });

  const last7=[];
  for(let i=6;i>=0;i--){
    const dt=new Date(); dt.setDate(dt.getDate()-i);
    const iso=dt.toISOString().split("T")[0];
    const P=activeEmps.filter(e=>attStatus(data,e.id,iso)==="P").length;
    const M=activeEmps.filter(e=>attStatus(data,e.id,iso)==="M").length;
    last7.push({d:fmtDate(iso),P,M,F:activeEmps.filter(e=>attStatus(data,e.id,iso)==="F").length});
  }

  const alerts=[];
  if(semReg>0) alerts.push({msg:`${semReg} func. sem ponto hoje`,color:C.yellow});
  if(activeEmps.length===0) alerts.push({msg:"Nenhum funcionário cadastrado",color:C.red});

  const Stat=({icon,label,value,sub,color,onClick})=>(
    <div onClick={onClick} style={{background:C.card,border:`1px solid ${C.border}`,padding:"14px",cursor:onClick?"pointer":"default",borderTop:`3px solid ${color}`,transition:"transform .15s"}}
      onMouseEnter={e=>onClick&&(e.currentTarget.style.transform="translateY(-2px)")}
      onMouseLeave={e=>e.currentTarget.style.transform="none"}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
        <div>
          <p style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:.7}}>{label}</p>
          <p style={{fontSize:28,fontWeight:900,fontFamily:"'Bebas Neue'",color:color,lineHeight:1.1,marginTop:4,letterSpacing:1}}>{value}</p>
          {sub&&<p style={{fontSize:11,color:C.subtle,marginTop:3}}>{sub}</p>}
        </div>
        <div style={{color,opacity:.5}}><Ic n={icon} s={22}/></div>
      </div>
    </div>
  );

  return(
    <div style={{display:"flex",flexDirection:"column",gap:14}} className="anim">
      {/* VERIFICAÇÃO DIÁRIA BANNER */}
      {checkPending&&(
        <button onClick={onDailyCheck} style={{background:`linear-gradient(135deg,${C.yellow}22,${C.yellow}08)`,border:`1.5px solid ${C.yellow}`,padding:"14px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",cursor:"pointer",width:"100%",borderLeft:`4px solid ${C.yellow}`}}>
          <div style={{display:"flex",alignItems:"center",gap:10,textAlign:"left"}}>
            <span style={{fontSize:28}}>🏗️</span>
            <div>
              <p style={{fontFamily:"'Bebas Neue'",fontSize:16,color:C.yellow,letterSpacing:1}}>VERIFICAÇÃO DIÁRIA PENDENTE</p>
              <p style={{fontSize:12,color:C.subtle,marginTop:2}}>Confirme se a equipe continua nas mesmas obras</p>
            </div>
          </div>
          <div style={{background:C.yellow,padding:"6px 14px",fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:13,color:C.bg,letterSpacing:.5,flexShrink:0}}>
            VERIFICAR
          </div>
        </button>
      )}
      {checkPending===false&&(
        <div style={{background:C.green+"15",border:`1px solid ${C.green}44`,padding:"10px 14px",display:"flex",alignItems:"center",gap:8,borderLeft:`3px solid ${C.green}`}}>
          <Ic n="check" s={15} style={{color:C.green,flexShrink:0}}/>
          <span style={{fontSize:12,color:C.green,fontWeight:600}}>Verificação diária concluída ✓</span>
        </div>
      )}
      {/* Other alerts */}
      {alerts.map((a,i)=>(
        <div key={i} style={{background:a.color+"10",border:`1px solid ${a.color}44`,padding:"10px 14px",display:"flex",alignItems:"center",gap:8,borderLeft:`3px solid ${a.color}`}}>
          <Ic n="alert" s={15} style={{color:a.color,flexShrink:0}}/>
          <span style={{fontSize:13,color:a.color,fontWeight:700,fontFamily:"'Barlow Condensed'",textTransform:"uppercase",letterSpacing:.5}}>{a.msg}</span>
        </div>
      ))}

      {/* Period strip */}
      <div style={{background:C.yellow,padding:"10px 16px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div>
          <p style={{fontFamily:"'Bebas Neue'",fontSize:15,color:C.bg,letterSpacing:2}}>
            {d<=15?"1ª QUINZENA":"2ª QUINZENA"} · {fullMonth(m).toUpperCase()} {y}
          </p>
          <p style={{fontSize:11,color:C.bg+"99",letterSpacing:.3}}>
            {qDays[0]&&fmtDate(qDays[0])} – {qDays[qDays.length-1]&&fmtDate(qDays[qDays.length-1])}/{String(m+1).padStart(2,"0")} · {qDays.length} dias
          </p>
        </div>
        <p style={{fontFamily:"'Bebas Neue'",fontSize:22,color:C.bg,letterSpacing:1}}>{fmt(qTotal)}</p>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
        <Stat icon="users" label="Funcionários" value={activeEmps.length} color={C.yellow} sub={`${data.obras.filter(o=>o.status==="active").length} obras`} onClick={()=>onTab("equipe")}/>
        <Stat icon="check" label="Presentes Hoje" value={presentes} color={C.green} sub={`${meiodia} meio dia`} onClick={()=>onTab("ponto")}/>
        <Stat icon="x" label="Ausentes" value={faltas} color={C.red} sub={`${semReg} s/ registro`} onClick={()=>onTab("ponto")}/>
        <Stat icon="money" label="Custo Quinzena" value={fmt(qTotal).replace("R$\xa0","").replace(",00","")} color={C.yellow} sub="acumulado"/>
      </div>

      {/* 7-day chart */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,padding:"14px 14px 8px"}}>
        <p style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>Presença — Últimos 7 dias</p>
        <ResponsiveContainer width="100%" height={110}>
          <BarChart data={last7} barSize={11}>
            <XAxis dataKey="d" tick={{fill:C.muted,fontSize:10}} axisLine={false} tickLine={false}/>
            <Tooltip contentStyle={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:0,fontSize:12}} cursor={{fill:C.border+"44"}}/>
            <Bar dataKey="P" name="Presentes" fill={C.green} radius={[2,2,0,0]}/>
            <Bar dataKey="M" name="Meio Dia" fill={C.yellow} radius={[2,2,0,0]}/>
            <Bar dataKey="F" name="Faltas" fill={C.red} radius={[2,2,0,0]}/>
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Quick actions */}
      <div style={{display:"flex",flexDirection:"column",gap:1}}>
        <p style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:8}}>Ações Rápidas</p>
        {[
          {l:"Registrar Ponto de Hoje",t:"ponto",color:C.yellow,icon:"clock"},
          {l:"Gerar Folha Quinzenal",t:"folha",color:C.green,icon:"dollar"},
          {l:"Cadastrar Funcionário",t:"equipe",color:C.blue,icon:"users"},
          {l:"Ver Relatórios",t:"relat",color:C.purple,icon:"chart"},
        ].map(a=>(
          <button key={a.t} onClick={()=>onTab(a.t)} style={{background:C.card,border:`1px solid ${C.border}`,borderLeft:`3px solid ${a.color}`,padding:"12px 14px",display:"flex",alignItems:"center",justifyContent:"space-between",cursor:"pointer",width:"100%",marginBottom:6}}>
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <div style={{color:a.color}}><Ic n={a.icon} s={16}/></div>
              <span style={{fontFamily:"'Barlow Condensed'",fontWeight:700,fontSize:15,color:C.text,letterSpacing:.3}}>{a.l}</span>
            </div>
            <Ic n="chevR" s={14} style={{color:C.muted}}/>
          </button>
        ))}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// OBRAS
// ═══════════════════════════════════════════════════════════════════
function Obras({data,update,showToast}){
  const empty={id:"",name:"",address:"",engineer:"",startDate:"",status:"active"};
  const [modal,setModal]=useState(false);
  const [form,setForm]=useState(empty);
  const F=k=>v=>setForm(f=>({...f,[k]:v}));
  const save=()=>{
    if(!form.name.trim()){showToast("Nome obrigatório","error");return;}
    const obras=form.id?data.obras.map(o=>o.id===form.id?form:o):[...data.obras,{...form,id:uid()}];
    update({...data,obras});setModal(false);showToast(form.id?"Obra atualizada!":"Obra cadastrada!");
  };
  const remove=id=>{
    if(data.employees.some(e=>e.obra===id)){showToast("Remova os funcionários primeiro.","error");return;}
    update({...data,obras:data.obras.filter(o=>o.id!==id)});showToast("Obra removida.");
  };
  const STATUS={active:{l:"Ativa",c:C.green},paused:{l:"Pausada",c:C.yellow},done:{l:"Concluída",c:C.muted}};
  return(
    <div style={{display:"flex",flexDirection:"column",gap:12}} className="anim">
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div><h2 style={{fontFamily:"'Bebas Neue'",fontSize:28,letterSpacing:2,color:C.yellow}}>Obras</h2>
          <p style={{color:C.muted,fontSize:13}}>{data.obras.length} cadastradas</p></div>
        <Btn onClick={()=>{setForm(empty);setModal(true)}}><Ic n="plus" s={16}/>Nova Obra</Btn>
      </div>
      {data.obras.map(o=>{
        const empCount=data.employees.filter(e=>e.obra===o.id).length;
        const s=STATUS[o.status]||STATUS.active;
        return(
          <div key={o.id} style={{background:C.card,border:`1px solid ${C.border}`,borderLeft:`4px solid ${s.c}`,padding:"14px 16px"}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
              <div style={{flex:1}}>
                <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
                  <span style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:17,letterSpacing:.3}}>{o.name}</span>
                  <Badge color={s.c}>{s.l}</Badge>
                </div>
                {o.address&&<p style={{fontSize:12,color:C.muted,marginTop:4}}>📍 {o.address}</p>}
                {o.engineer&&<p style={{fontSize:12,color:C.subtle,marginTop:2}}>👷 {o.engineer}</p>}
                {o.startDate&&<p style={{fontSize:12,color:C.muted,marginTop:2}}>🗓 {fmtDate(o.startDate)}</p>}
                <p style={{fontSize:12,color:C.yellow,marginTop:4,fontWeight:700}}>{empCount} funcionário{empCount!==1?"s":""}</p>
              </div>
              <div style={{display:"flex",gap:6}}>
                <Btn onClick={()=>{setForm(o);setModal(true)}} v="ghost" size="sm"><Ic n="edit" s={13}/></Btn>
                <Btn onClick={()=>remove(o.id)} v="danger" size="sm"><Ic n="trash" s={13}/></Btn>
              </div>
            </div>
          </div>
        );
      })}
      {modal&&(
        <Modal title={form.id?"Editar Obra":"Nova Obra"} onClose={()=>setModal(false)}>
          <div style={{display:"flex",flexDirection:"column",gap:12}}>
            <Inp label="Nome da Obra *" value={form.name} onChange={F("name")} placeholder="Residencial Aurora"/>
            <Inp label="Endereço" value={form.address} onChange={F("address")} placeholder="Rua, número, bairro..."/>
            <Inp label="Engenheiro Responsável" value={form.engineer} onChange={F("engineer")}/>
            <Inp label="Data de Início" type="date" value={form.startDate} onChange={F("startDate")}/>
            <Sel label="Status" value={form.status} onChange={F("status")}
              options={[{v:"active",l:"Ativa"},{v:"paused",l:"Pausada"},{v:"done",l:"Concluída"}]}/>
            <div style={{display:"flex",gap:8,marginTop:8}}>
              <Btn v="ghost" onClick={()=>setModal(false)} full>Cancelar</Btn>
              <Btn onClick={save} full><Ic n="check" s={16}/>{form.id?"Salvar":"Cadastrar"}</Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// EQUIPE
// ═══════════════════════════════════════════════════════════════════
function Equipe({data,update,showToast}) {
  const emptyEmp = {
    id: "",
    name: "",
    role: "",
    cpf: "",
    phone: "",
    pixKey: "",
    dailyRate: "",
    vtDaily: "",
    vrDaily: "",
    obra: "",
    active: true,
    startDate: "",
    endDate: "",
    terminationReason: "",
    lastObra: "",
  };

  const [modal, setModal] = useState(false);
  const [advModal, setAdvModal] = useState(null);
  const [form, setForm] = useState(emptyEmp);
  const [search, setSearch] = useState("");
  const [filterObra, setFilterObra] = useState("all");
  const [expandedId, setExpandedId] = useState(null);
  const [advForm, setAdvForm] = useState({
    amount: "",
    description: "",
    date: today(),
  });

  const F = k => v => setForm(f => ({ ...f, [k]: v }));
  const obraName = id => data.obras.find(o => o.id === id)?.name || "—";
  const empAdvances = eid => (data.advances || []).filter(a => a.empId === eid);

  const saveEmp = () => {
    if (!form.name.trim() || !form.dailyRate || !form.startDate || !form.obra) {
      showToast("Nome, admissão, diária e obra são obrigatórios", "error");
      return;
    }

    if (form.active === false && !form.endDate) {
      showToast("Informe a data de término para inativar/demitir o funcionário", "error");
      return;
    }

    const before = data.employees.find(e => e.id === form.id);

    const payload = {
      ...form,
      id: form.id || uid(),
      dailyRate: parseFloat(form.dailyRate) || 0,
      vtDaily: parseFloat(form.vtDaily || 0) || 0,
      vrDaily: parseFloat(form.vrDaily || 0) || 0,
      active: form.active !== false,
      endDate: form.active === false ? form.endDate : "",
      terminationReason: form.active === false ? (form.terminationReason || "Inativado") : "",
      lastObra: form.active === false ? (before?.obra || form.obra) : (form.lastObra || ""),
    };

    const changeLog = [...(data.changeLog || [])];

    if (!form.id) {
      changeLog.push({
        id: uid(),
        date: today(),
        type: "created",
        empId: payload.id,
        empName: payload.name,
        message: `Funcionário cadastrado em ${today()}`,
      });
    }

    if (before && before.obra !== payload.obra) {
      const from = obraName(before.obra);
      const to = obraName(payload.obra);

      changeLog.push({
        id: uid(),
        date: today(),
        empId: payload.id,
        empName: payload.name,
        type: "transfer",
        from,
        to,
        message: `${payload.name} transferido de ${from} para ${to}`,
      });
    }

    if (before && before.active !== false && payload.active === false) {
      changeLog.push({
        id: uid(),
        date: payload.endDate || today(),
        empId: payload.id,
        empName: payload.name,
        type: "dismissal",
        from: obraName(before.obra),
        message: `${payload.name} inativado/demitido em ${payload.endDate}`,
      });
    }

    const employees = form.id
      ? data.employees.map(e => e.id === form.id ? payload : e)
      : [...data.employees, payload];

    update({ ...data, employees, changeLog });
    setModal(false);
    showToast(form.id ? "Funcionário atualizado!" : "Funcionário cadastrado!");
  };

  const archiveEmp = id => {
    const emp = data.employees.find(e => e.id === id);
    if (!emp) return;

    const ok = window.confirm(
      `Deseja inativar ${emp.name}? O histórico de ponto, folha e adiantamentos será preservado.`
    );

    if (!ok) return;

    const endDate = window.prompt("Informe a data de término no formato AAAA-MM-DD:", today());

    if (!endDate) {
      showToast("Data de término obrigatória para inativar", "error");
      return;
    }

    const employees = data.employees.map(e =>
      e.id === id
        ? {
            ...e,
            active: false,
            endDate,
            terminationReason: "Inativado",
            lastObra: e.obra,
          }
        : e
    );

    const changeLog = [
      ...(data.changeLog || []),
      {
        id: uid(),
        date: endDate,
        empId: emp.id,
        empName: emp.name,
        type: "dismissal",
        from: obraName(emp.obra),
        message: `${emp.name} foi inativado em ${endDate}`,
      },
    ];

    update({ ...data, employees, changeLog });
    showToast("Funcionário inativado com histórico preservado.");
  };

  const saveAdv = () => {
    if (!advForm.amount || isNaN(advForm.amount)) {
      showToast("Valor inválido", "error");
      return;
    }

    const advances = [
      ...(data.advances || []),
      {
        id: uid(),
        empId: advModal,
        date: advForm.date,
        amount: parseFloat(advForm.amount),
        description: advForm.description || "Adiantamento",
      },
    ];

    update({ ...data, advances });
    setAdvModal(null);
    setAdvForm({ amount: "", description: "", date: today() });
    showToast("Adiantamento registrado!");
  };

  const removeAdv = id => {
    update({
      ...data,
      advances: (data.advances || []).filter(a => a.id !== id),
    });
  };

  const list = data.employees.filter(e =>
    (filterObra === "all" || e.obra === filterObra || e.lastObra === filterObra) &&
    (e.name || "").toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }} className="anim">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <h2 style={{ fontFamily: "'Bebas Neue'", fontSize: 28, letterSpacing: 2, color: C.yellow }}>
            Equipe
          </h2>
          <p style={{ color: C.muted, fontSize: 13 }}>
            {data.employees.length} funcionários cadastrados
          </p>
        </div>

        <Btn onClick={() => {
          setForm({ ...emptyEmp, obra: data.obras[0]?.id || "" });
          setModal(true);
        }}>
          <Ic n="plus" s={16} />
          Novo
        </Btn>
      </div>

      <Inp value={search} onChange={setSearch} placeholder=" Buscar por nome..." />

      <Sel
        value={filterObra}
        onChange={setFilterObra}
        options={[
          { v: "all", l: "Todas as obras" },
          ...data.obras.map(o => ({ v: o.id, l: o.name })),
        ]}
      />

      {list.length === 0 && (
        <div style={{ textAlign: "center", padding: "40px 0", color: C.muted }}>
          <div style={{ fontSize: 36, marginBottom: 8 }}></div>
          <p>Nenhum funcionário encontrado.</p>
        </div>
      )}

      {list.map(e => {
        const advs = empAdvances(e.id);
        const totalAdv = advs.reduce((s, a) => s + (a.amount || 0), 0);
        const exp = expandedId === e.id;

        return (
          <div
            key={e.id}
            style={{
              background: C.card,
              border: `1px solid ${C.border}`,
              borderLeft: `4px solid ${e.active === false ? C.muted : C.yellow}`,
            }}
          >
            <div style={{ padding: "13px 15px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div style={{ flex: 1, cursor: "pointer" }} onClick={() => setExpandedId(exp ? null : e.id)}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                    <span style={{ fontFamily: "'Barlow Condensed'", fontWeight: 800, fontSize: 17 }}>
                      {e.name}
                    </span>

                    {e.active === false && <Badge color={C.muted}>Inativo</Badge>}
                    {e.role && <Badge color={C.subtle}>{e.role}</Badge>}
                  </div>

                  <p style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>
                    {obraName(e.obra)}
                  </p>

                  <div style={{ display: "flex", gap: 10, marginTop: 4, flexWrap: "wrap" }}>
                    <span style={{ fontSize: 14, color: C.yellow, fontWeight: 700 }}>
                      {fmt(e.dailyRate)}
                      <span style={{ fontSize: 10, color: C.muted, fontWeight: 400 }}>/dia</span>
                    </span>

                    {e.vtDaily > 0 && <span style={{ fontSize: 12, color: C.blue }}>VT: {fmt(e.vtDaily)}</span>}
                    {e.vrDaily > 0 && <span style={{ fontSize: 12, color: C.green }}>VR: {fmt(e.vrDaily)}</span>}
                    {totalAdv > 0 && <span style={{ fontSize: 12, color: C.red }}>Adiant: {fmt(totalAdv)}</span>}
                  </div>
                </div>

                <div style={{ display: "flex", gap: 5 }}>
                  <Btn
                    onClick={() => {
                      setForm({
                        ...e,
                        dailyRate: String(e.dailyRate),
                        vtDaily: String(e.vtDaily || 0),
                        vrDaily: String(e.vrDaily || 0),
                        endDate: e.endDate || "",
                        terminationReason: e.terminationReason || "",
                        lastObra: e.lastObra || "",
                      });
                      setModal(true);
                    }}
                    v="ghost"
                    size="sm"
                  >
                    <Ic n="edit" s={13} />
                  </Btn>

                  <Btn onClick={() => archiveEmp(e.id)} v="danger" size="sm">
                    <Ic n="x" s={13} />
                  </Btn>
                </div>
              </div>
            </div>

            {exp && (
              <div style={{ borderTop: `1px solid ${C.border}`, padding: "12px 15px", background: C.surface }}>
                {e.phone && <p style={{ fontSize: 12, color: C.subtle, marginBottom: 4 }}><Ic n="phone" s={12} /> {e.phone}</p>}
                {e.cpf && <p style={{ fontSize: 12, color: C.subtle, marginBottom: 4 }}>CPF: {e.cpf}</p>}
                {e.pixKey && <p style={{ fontSize: 12, color: C.subtle, marginBottom: 4 }}>PIX: {e.pixKey}</p>}
                {e.startDate && <p style={{ fontSize: 12, color: C.subtle, marginBottom: 4 }}>Admissão: {fmtDate(e.startDate)}</p>}
                {e.endDate && <p style={{ fontSize: 12, color: C.red, marginBottom: 8 }}>Término: {fmtDate(e.endDate)}</p>}

                {e.active !== false && (
                  <>
                    <Divider />

                    <div style={{ marginBottom: 12 }}>
                      <p style={{
                        fontSize: 11,
                        fontWeight: 700,
                        color: C.yellow,
                        textTransform: "uppercase",
                        letterSpacing: .5,
                        marginBottom: 8,
                      }}>
                        Transferência Rápida
                      </p>

                      <Sel
                        value=""
                        onChange={v => {
                          if (!v) return;

                          const from = obraName(e.obra);
                          const to = data.obras.find(o => o.id === v)?.name || "?";

                          const changeLog = [
                            ...(data.changeLog || []),
                            {
                              id: uid(),
                              date: today(),
                              empId: e.id,
                              empName: e.name,
                              type: "transfer",
                              from,
                              to,
                              message: `${e.name} transferido de ${from} para ${to}`,
                            },
                          ];

                          update({
                            ...data,
                            employees: data.employees.map(emp =>
                              emp.id === e.id
                                ? { ...emp, obra: v, lastObra: emp.obra }
                                : emp
                            ),
                            changeLog,
                          });

                          showToast(`${e.name} transferido!`);
                          setExpandedId(null);
                        }}
                        options={[
                          { v: "", l: "→ Transferir para..." },
                          ...data.obras
                            .filter(o => o.id !== e.obra && o.status !== "done")
                            .map(o => ({ v: o.id, l: o.name })),
                        ]}
                      />
                    </div>
                  </>
                )}

                <Divider />

                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                  <span style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: .5 }}>
                    Adiantamentos
                  </span>

                  <Btn onClick={() => setAdvModal(e.id)} v="warning" size="sm">
                    <Ic n="plus" s={12} />
                    Novo
                  </Btn>
                </div>

                {advs.length === 0 && <p style={{ fontSize: 12, color: C.muted }}>Nenhum adiantamento.</p>}

                {advs.map(a => (
                  <div
                    key={a.id}
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      padding: "6px 0",
                      borderBottom: `1px solid ${C.border}`,
                    }}
                  >
                    <div>
                      <p style={{ fontSize: 13, fontWeight: 600 }}>{a.description}</p>
                      <p style={{ fontSize: 11, color: C.muted }}>{fmtDate(a.date)}</p>
                    </div>

                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <span style={{ color: C.red, fontWeight: 700, fontSize: 14 }}>{fmt(a.amount)}</span>
                      <Btn onClick={() => removeAdv(a.id)} v="danger" size="sm">
                        <Ic n="trash" s={12} />
                      </Btn>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        );
      })}

      {modal && (
        <Modal title={form.id ? "Editar Funcionário" : "Novo Funcionário"} onClose={() => setModal(false)} wide>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            <div style={{ gridColumn: "1/-1" }}>
              <Inp label="Nome Completo *" value={form.name} onChange={F("name")} placeholder="João da Silva" />
            </div>

            <Inp label="Cargo / Função" value={form.role} onChange={F("role")} placeholder="Pedreiro" />
            <Inp label="Admissão *" type="date" value={form.startDate} onChange={F("startDate")} />
            <Inp label="Diária (R$) *" type="number" value={form.dailyRate} onChange={F("dailyRate")} placeholder="180.00" />

            <div style={{ gridColumn: "1/-1" }}>
              <Sel
                label="Obra *"
                value={form.obra}
                onChange={F("obra")}
                options={data.obras.map(o => ({ v: o.id, l: o.name }))}
              />
            </div>

            <Inp label="VT diário" type="number" value={form.vtDaily} onChange={F("vtDaily")} placeholder="0.00" />
            <Inp label="VR/VA diário" type="number" value={form.vrDaily} onChange={F("vrDaily")} placeholder="0.00" />
            <Inp label="CPF" value={form.cpf} onChange={v => F("cpf")(fmtCPF(v))} placeholder="000.000.000-00" />
            <Inp label="Telefone" value={form.phone} onChange={v => F("phone")(fmtPhone(v))} placeholder="(00) 00000-0000" />

            <div style={{ gridColumn: "1/-1" }}>
              <Inp label="Chave PIX" value={form.pixKey} onChange={F("pixKey")} placeholder="CPF, e-mail ou telefone" />
            </div>

            <Sel
              label="Status"
              value={String(form.active !== false)}
              onChange={v => F("active")(v === "true")}
              options={[
                { v: "true", l: "Ativo" },
                { v: "false", l: "Inativo / Demitido" },
              ]}
            />

            {form.active === false && (
              <>
                <Inp
                  label="Data de término *"
                  type="date"
                  value={form.endDate}
                  onChange={F("endDate")}
                />

                <div style={{ gridColumn: "1/-1" }}>
                  <Inp
                    label="Motivo da inativação"
                    value={form.terminationReason}
                    onChange={F("terminationReason")}
                    placeholder="Ex.: Demitido, fim de contrato, desligamento..."
                  />
                </div>
              </>
            )}
          </div>

          <div style={{ display: "flex", gap: 8, marginTop: 16 }}>
            <Btn v="ghost" onClick={() => setModal(false)} full>Cancelar</Btn>
            <Btn onClick={saveEmp} full>
              <Ic n="check" s={16} />
              {form.id ? "Salvar" : "Cadastrar"}
            </Btn>
          </div>
        </Modal>
      )}

      {advModal && (
        <Modal title="Novo Adiantamento" onClose={() => setAdvModal(null)}>
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <Inp
              label="Valor (R$) *"
              type="number"
              value={advForm.amount}
              onChange={v => setAdvForm(f => ({ ...f, amount: v }))}
              placeholder="500.00"
            />

            <Inp
              label="Descrição"
              value={advForm.description}
              onChange={v => setAdvForm(f => ({ ...f, description: v }))}
              placeholder="Adiantamento de quinzena"
            />

            <Inp
              label="Data"
              type="date"
              value={advForm.date}
              onChange={v => setAdvForm(f => ({ ...f, date: v }))}
            />

            <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
              <Btn v="ghost" onClick={() => setAdvModal(null)} full>Cancelar</Btn>
              <Btn v="warning" onClick={saveAdv} full>
                <Ic n="check" s={16} />
                Registrar
              </Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}
// ═══════════════════════════════════════════════════════════════════
// PONTO
// ═══════════════════════════════════════════════════════════════════
function Ponto({data,update,showToast,onDailyCheck}) {
  const [selDate, setSelDate] = useState(today());
  const [filterObra, setFilterObra] = useState("all");
  const [noteModal, setNoteModal] = useState(null);
  const [noteText, setNoteText] = useState("");
  const [otModal, setOtModal] = useState(null);
  const [otHours, setOtHours] = useState("0");
  const [movementModal, setMovementModal] = useState(null);

  const dailyCheckPending =
    selDate === today() &&
    data.employees.filter(e => e.active !== false).length > 0 &&
    data.dailyCheckDate !== today();

  const requireDailyCheck = () => {
    if (!dailyCheckPending) return false;

    showToast(
      "Antes de lançar o ponto, confirme se a equipe permanece sem alterações ou movimente o trabalhador individualmente.",
      "warn"
    );

    return true;
  };

  const confirmTeamWithoutChanges = () => {
    update({
      ...data,
      dailyCheckDate: today(),
      changeLog: [
        ...(data.changeLog || []),
        {
          id: uid(),
          date: today(),
          type: "daily_check",
          message: "Verificação diária concluída: equipe sem alterações.",
        },
      ],
    });

    showToast("Equipe confirmada sem alterações.");
  };

  const list = data.employees.filter(e =>
    (filterObra === "all" || e.obra === filterObra) &&
    e.active !== false
  );

  const obraName = id => data.obras.find(o => o.id === id)?.name || "—";

  const setAtt = (eid, status) => {
    if (requireDailyCheck()) return;

    const prev = getAtt(data, eid, selDate) || { status: null, ot: 0, note: "" };
    const v = prev.status === status ? null : status;

    update({
      ...data,
      attendance: {
        ...data.attendance,
        [eid]: {
          ...(data.attendance[eid] || {}),
          [selDate]: {
            ...prev,
            status: v,
          },
        },
      },
    });
  };

  const saveNote = () => {
    if (requireDailyCheck()) return;

    const prev = getAtt(data, noteModal, selDate) || { status: null, ot: 0, note: "" };

    update({
      ...data,
      attendance: {
        ...data.attendance,
        [noteModal]: {
          ...(data.attendance[noteModal] || {}),
          [selDate]: {
            ...prev,
            note: noteText,
          },
        },
      },
    });

    setNoteModal(null);
    showToast("Observação salva!");
  };

  const saveOT = () => {
    if (requireDailyCheck()) return;

    const prev = getAtt(data, otModal, selDate) || { status: null, ot: 0, note: "" };

    update({
      ...data,
      attendance: {
        ...data.attendance,
        [otModal]: {
          ...(data.attendance[otModal] || {}),
          [selDate]: {
            ...prev,
            ot: parseFloat(otHours) || 0,
          },
        },
      },
    });

    setOtModal(null);
    showToast("Hora extra registrada!");
  };

  const markAll = status => {
    if (requireDailyCheck()) return;

    const att = { ...data.attendance };

    list.forEach(e => {
      att[e.id] = {
        ...(att[e.id] || {}),
        [selDate]: {
          ...(getAtt(data, e.id, selDate) || {}),
          status,
        },
      };
    });

    update({ ...data, attendance: att });
    showToast("Ponto marcado para todos!");
  };

  const counts = { P: 0, M: 0, F: 0 };

  list.forEach(e => {
    const s = attStatus(data, e.id, selDate);
    if (s) counts[s] = (counts[s] || 0) + 1;
  });

  const semReg = list.length - counts.P - counts.M - counts.F;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }} className="anim">
      <div>
        <h2 style={{ fontFamily: "'Bebas Neue'", fontSize: 28, letterSpacing: 2, color: C.yellow }}>
          Registro de Ponto
        </h2>

        <p style={{ color: C.muted, fontSize: 13 }}>
          Marque a presença diária e movimente trabalhadores individualmente
        </p>
      </div>

      <Inp label="Data" type="date" value={selDate} onChange={setSelDate} max={today()} />

      {dailyCheckPending && (
        <div
          style={{
            background: `${C.yellow}18`,
            border: `1.5px solid ${C.yellow}`,
            borderLeft: `4px solid ${C.yellow}`,
            padding: "12px 14px",
          }}
        >
          <p
            style={{
              color: C.yellow,
              fontFamily: "'Barlow Condensed'",
              fontWeight: 800,
              letterSpacing: .5,
              textTransform: "uppercase",
              marginBottom: 8,
            }}
          >
            Verificação obrigatória pendente
          </p>

          <p style={{ color: C.subtle, fontSize: 12, marginBottom: 10 }}>
            Se algum trabalhador foi transferido ou demitido, use os botões no card do próprio trabalhador.
          </p>

          <Btn onClick={confirmTeamWithoutChanges} v="ghost" full>
            Confirmar equipe sem alterações hoje
          </Btn>
        </div>
      )}

      <Sel
        value={filterObra}
        onChange={setFilterObra}
        options={[
          { v: "all", l: "Todas as obras" },
          ...data.obras.map(o => ({ v: o.id, l: o.name })),
        ]}
      />

      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 6 }}>
        {[
          ["P", counts.P, C.green, "Pres."],
          ["–", semReg, C.muted, "S/reg"],
          ["M", counts.M, C.yellow, "½dia"],
          ["F", counts.F, C.red, "Falta"],
        ].map(([k, n, c, l]) => (
          <div
            key={k}
            style={{
              background: C.card,
              border: `1px solid ${c}44`,
              borderTop: `3px solid ${c}`,
              padding: "8px",
              textAlign: "center",
            }}
          >
            <p style={{ fontSize: 22, fontWeight: 900, fontFamily: "'Bebas Neue'", color: c, letterSpacing: 1 }}>
              {n}
            </p>

            <p style={{ fontSize: 10, color: C.muted }}>
              {l}
            </p>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 8 }}>
        <Btn onClick={() => markAll("P")} v="success" size="sm" full>
          <Ic n="check" s={14} />
          Todos Presentes
        </Btn>

        <Btn onClick={() => markAll("F")} v="danger" size="sm" full>
          <Ic n="x" s={14} />
          Todos com Falta
        </Btn>
      </div>

      {list.map(e => {
        const att = getAtt(data, e.id, selDate);
        const status = att?.status;
        const ot = att?.ot || 0;
        const note = att?.note || "";
        const borderCol = status === "P" ? C.green : status === "M" ? C.yellow : status === "F" ? C.red : C.border;

        return (
          <div
            key={e.id}
            style={{
              background: C.card,
              border: `1px solid ${C.border}`,
              borderLeft: `4px solid ${borderCol}`,
              padding: "12px 13px",
            }}
          >
            <div style={{ marginBottom: 9 }}>
              <p style={{ fontFamily: "'Barlow Condensed'", fontWeight: 800, fontSize: 16, letterSpacing: .3 }}>
                {e.name}
              </p>

              <p style={{ fontSize: 11, color: C.muted }}>
                {obraName(e.obra)}
                {e.role ? ` · ${e.role}` : ""}
              </p>

              {ot > 0 && <Badge color={C.purple}>{ot}h extra</Badge>}

              {note && (
                <p style={{ fontSize: 11, color: C.subtle, marginTop: 2, fontStyle: "italic" }}>
                  "{note}"
                </p>
              )}
            </div>

            <div style={{ display: "flex", gap: 5, marginBottom: 8 }}>
              {[
                ["P", "check", C.green, "PRESENTE"],
                ["M", "money", C.yellow, "MEIO DIA"],
                ["F", "x", C.red, "FALTA"],
              ].map(([s, ic, col, lbl]) => (
                <button
                  key={s}
                  onClick={() => setAtt(e.id, s)}
                  style={{
                    flex: 1,
                    padding: "8px 4px",
                    border: `2px solid ${status === s ? col : C.border}`,
                    background: status === s ? col + "22" : "transparent",
                    color: status === s ? col : C.muted,
                    cursor: "pointer",
                    fontSize: 11,
                    fontWeight: 800,
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    gap: 2,
                    fontFamily: "'Barlow Condensed'",
                    transition: "all .15s",
                  }}
                >
                  <Ic n={ic} s={14} />
                  {lbl}
                </button>
              ))}
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 5, marginBottom: 5 }}>
              <Btn
                onClick={() => setMovementModal({ emp: e, mode: "transfer" })}
                v="warning"
                size="sm"
                full
              >
                Transferir
              </Btn>

              <Btn
                onClick={() => setMovementModal({ emp: e, mode: "dismiss" })}
                v="danger"
                size="sm"
                full
              >
                Demitir
              </Btn>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 5 }}>
              <Btn
                onClick={() => {
                  if (requireDailyCheck()) return;
                  setOtModal(e.id);
                  setOtHours(String(ot));
                }}
                v="ghost"
                size="sm"
                full
              >
                <Ic n="clock" s={12} />
                Hora Extra
              </Btn>

              <Btn
                onClick={() => {
                  if (requireDailyCheck()) return;
                  setNoteModal(e.id);
                  setNoteText(note);
                }}
                v="ghost"
                size="sm"
                full
              >
                <Ic n="edit" s={12} />
                Observação
              </Btn>
            </div>
          </div>
        );
      })}

      {movementModal && (
        <WorkerMovementModal
          data={data}
          update={update}
          showToast={showToast}
          employee={movementModal.emp}
          initialMode={movementModal.mode}
          onClose={() => setMovementModal(null)}
        />
      )}

      {noteModal && (
        <Modal title="Observação" onClose={() => setNoteModal(null)}>
          <Inp label="Observação" value={noteText} onChange={setNoteText} placeholder="Ex: Saiu mais cedo..." />

          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            <Btn v="ghost" onClick={() => setNoteModal(null)} full>
              Cancelar
            </Btn>

            <Btn onClick={saveNote} full>
              <Ic n="check" s={16} />
              Salvar
            </Btn>
          </div>
        </Modal>
      )}

      {otModal && (
        <Modal title="Horas Extras" onClose={() => setOtModal(null)}>
          <Inp
            label="Quantidade de horas"
            type="number"
            value={otHours}
            onChange={setOtHours}
            placeholder="Ex: 2.5"
          />

          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            <Btn v="ghost" onClick={() => setOtModal(null)} full>
              Cancelar
            </Btn>

            <Btn onClick={saveOT} full v="info">
              <Ic n="check" s={16} />
              Registrar
            </Btn>
          </div>
        </Modal>
      )}
    </div>
  );
}

function WorkerMovementModal({ data, update, showToast, employee, initialMode = "transfer", onClose }) {
  const [mode, setMode] = useState(initialMode);
  const [newObra, setNewObra] = useState("");
  const [endDate, setEndDate] = useState(today());
  const [reason, setReason] = useState("Demitido");

  const activeObras = (data.obras || []).filter(o => o.status !== "done");
  const obraName = id => data.obras.find(o => o.id === id)?.name || "—";

  const saveTransfer = () => {
    if (!newObra) {
      showToast("Selecione a nova obra.", "error");
      return;
    }

    if (newObra === employee.obra) {
      showToast("Selecione uma obra diferente da atual.", "error");
      return;
    }

    const from = obraName(employee.obra);
    const to = obraName(newObra);

    const employees = data.employees.map(emp =>
      emp.id === employee.id
        ? {
            ...emp,
            obra: newObra,
            lastObra: emp.obra,
            active: true,
            endDate: "",
            terminationReason: "",
          }
        : emp
    );

    const changeLog = [
      ...(data.changeLog || []),
      {
        id: uid(),
        date: today(),
        empId: employee.id,
        empName: employee.name,
        type: "transfer",
        from,
        to,
        message: `${employee.name} transferido de ${from} para ${to}`,
      },
    ];

    update({
      ...data,
      employees,
      changeLog,
      dailyCheckDate: today(),
    });

    showToast(`${employee.name} transferido para ${to}.`);
    onClose();
  };

  const saveDismissal = () => {
    if (!endDate) {
      showToast("Informe a data de término.", "error");
      return;
    }

    const from = obraName(employee.obra);

    const employees = data.employees.map(emp =>
      emp.id === employee.id
        ? {
            ...emp,
            active: false,
            endDate,
            terminationReason: reason || "Demitido",
            lastObra: emp.obra,
          }
        : emp
    );

    const changeLog = [
      ...(data.changeLog || []),
      {
        id: uid(),
        date: endDate,
        empId: employee.id,
        empName: employee.name,
        type: "dismissal",
        from,
        message: `${employee.name} demitido/inativado em ${endDate}`,
      },
    ];

    update({
      ...data,
      employees,
      changeLog,
      dailyCheckDate: today(),
    });

    showToast(`${employee.name} demitido/inativado.`);
    onClose();
  };

  const save = () => {
    if (mode === "transfer") {
      saveTransfer();
    } else {
      saveDismissal();
    }
  };

  return (
    <Modal
      title={mode === "transfer" ? "Transferir Trabalhador" : "Demitir Trabalhador"}
      onClose={onClose}
    >
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <div
          style={{
            background: C.card,
            border: `1px solid ${C.border}`,
            borderLeft: `4px solid ${mode === "transfer" ? C.yellow : C.red}`,
            padding: 12,
          }}
        >
          <p style={{
            fontFamily: "'Barlow Condensed'",
            fontWeight: 800,
            fontSize: 18,
            color: C.text,
          }}>
            {employee.name}
          </p>

          <p style={{ fontSize: 12, color: C.muted }}>
            Obra atual: {obraName(employee.obra)}
            {employee.role ? ` · ${employee.role}` : ""}
          </p>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
          <Btn
            v={mode === "transfer" ? "warning" : "ghost"}
            onClick={() => setMode("transfer")}
            full
          >
            Transferir
          </Btn>

          <Btn
            v={mode === "dismiss" ? "danger" : "ghost"}
            onClick={() => setMode("dismiss")}
            full
          >
            Demitir
          </Btn>
        </div>

        {mode === "transfer" && (
          <Sel
            label="Nova obra *"
            value={newObra}
            onChange={setNewObra}
            options={[
              { v: "", l: "Selecione a nova obra" },
              ...activeObras
                .filter(o => o.id !== employee.obra)
                .map(o => ({ v: o.id, l: o.name })),
            ]}
          />
        )}

        {mode === "dismiss" && (
          <>
            <Inp
              label="Data de término *"
              type="date"
              value={endDate}
              onChange={setEndDate}
            />

            <Inp
              label="Motivo"
              value={reason}
              onChange={setReason}
              placeholder="Ex.: Demitido, fim de contrato, desligamento..."
            />
          </>
        )}

        <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
          <Btn v="ghost" onClick={onClose} full>
            Cancelar
          </Btn>

          <Btn v={mode === "transfer" ? "warning" : "danger"} onClick={save} full>
            <Ic n="check" s={16} />
            {mode === "transfer" ? "Confirmar Transferência" : "Confirmar Demissão"}
          </Btn>
        </div>
      </div>
    </Modal>
  );
}

// ═══════════════════════════════════════════════════════════════════
// FOLHA
// ═══════════════════════════════════════════════════════════════════
function Folha({ data, showToast }) {
  const now = new Date();

  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth());
  const [q, setQ] = useState(now.getDate() <= 15 ? "1" : "2");
  const [filterObra, setFilterObra] = useState("all");
  const [expandedId, setExpandedId] = useState(null);

  const { q1, q2 } = getQ(year, month);
  const days = q === "1" ? q1 : q2;

  const obraName = id => data.obras.find(o => o.id === id)?.name || "—";
  const periodLabel = `${q === "1" ? "1ª" : "2ª"} Quinzena de ${fullMonth(month)} ${year}`;

  const calcRow = e => {
    let gross = 0;
    let presentes = 0;
    let meiodia = 0;
    let faltas = 0;
    let semRegistro = 0;
    let ot = 0;
    let vt = 0;
    let vr = 0;

    days.forEach(d => {
      const a = getAtt(data, e.id, d);
      const s = a?.status;
      const o = a?.ot || 0;

      if (s === "P") {
        gross += e.dailyRate || 0;
        presentes++;
        ot += o;
        vt += e.vtDaily || 0;
        vr += e.vrDaily || 0;
      } else if (s === "M") {
        gross += (e.dailyRate || 0) * 0.5;
        meiodia++;
        ot += o;
        vt += (e.vtDaily || 0) * 0.5;
        vr += (e.vrDaily || 0) * 0.5;
      } else if (s === "F") {
        faltas++;
      } else {
        semRegistro++;
      }
    });

    const advTotal = (data.advances || [])
      .filter(a => a.empId === e.id && a.date >= days[0] && a.date <= days[days.length - 1])
      .reduce((s, a) => s + (a.amount || 0), 0);

    return {
      ...e,
      gross,
      presentes,
      meiodia,
      faltas,
      semRegistro,
      ot,
      vt,
      vr,
      advances: advTotal,
      net: gross + vt + vr - advTotal,
      days: days.length,
    };
  };

  const hasAttendanceInPeriod = e =>
    days.some(d => {
      const a = getAtt(data, e.id, d);
      return a?.status || a?.ot || a?.note;
    });

  const belongsToSelectedObra = e =>
    filterObra === "all" || e.obra === filterObra || e.lastObra === filterObra;

  const rows = data.employees
    .filter(e => belongsToSelectedObra(e))
    .filter(e => e.active !== false || hasAttendanceInPeriod(e))
    .map(calcRow)
    .filter(r =>
      r.presentes > 0 ||
      r.meiodia > 0 ||
      r.faltas > 0 ||
      r.advances > 0 ||
      r.gross > 0
    );

  const T = {
    gross: rows.reduce((s, r) => s + r.gross, 0),
    vt: rows.reduce((s, r) => s + r.vt, 0),
    vr: rows.reduce((s, r) => s + r.vr, 0),
    advances: rows.reduce((s, r) => s + r.advances, 0),
    net: rows.reduce((s, r) => s + r.net, 0),
  };

  const printPDF = () => {
    const html = `
      <html>
        <head>
          <title>Folha - ${periodLabel}</title>
          <style>
            body {
              font-family: Arial, sans-serif;
              padding: 30px;
              color: #111;
            }

            h1, h2 {
              margin: 0;
            }

            table {
              width: 100%;
              border-collapse: collapse;
              margin-top: 20px;
              font-size: 12px;
            }

            th, td {
              border: 1px solid #ccc;
              padding: 6px;
              text-align: left;
            }

            th {
              background: #f0f0f0;
            }

            .total {
              font-weight: bold;
              background: #f7f7f7;
            }

            .signatures {
              margin-top: 50px;
              display: flex;
              justify-content: space-between;
              gap: 40px;
            }

            .signature {
              flex: 1;
              border-top: 1px solid #111;
              padding-top: 8px;
              text-align: center;
            }
          </style>
        </head>

        <body>
          <h1>${data.config.companyName || "ArcD Obras"}</h1>
          ${data.config.cnpj ? `<p>CNPJ: ${data.config.cnpj}</p>` : ""}
          <h2>Folha de Pagamento — ${periodLabel}</h2>

          <table>
            <thead>
              <tr>
                <th>Funcionário</th>
                <th>Cargo</th>
                <th>Obra</th>
                <th>P</th>
                <th>M</th>
                <th>F</th>
                <th>S/R</th>
                <th>HE</th>
                <th>Diária</th>
                <th>Bruto</th>
                <th>VT</th>
                <th>VR</th>
                <th>Adiant.</th>
                <th>Líquido</th>
              </tr>
            </thead>

            <tbody>
              ${rows.map(r => `
                <tr>
                  <td>${r.name}</td>
                  <td>${r.role || "-"}</td>
                  <td>${obraName(r.obra)}</td>
                  <td>${r.presentes}</td>
                  <td>${r.meiodia}</td>
                  <td>${r.faltas}</td>
                  <td>${r.semRegistro}</td>
                  <td>${r.ot || 0}h</td>
                  <td>R$ ${(r.dailyRate || 0).toFixed(2)}</td>
                  <td>R$ ${r.gross.toFixed(2)}</td>
                  <td>R$ ${r.vt.toFixed(2)}</td>
                  <td>R$ ${r.vr.toFixed(2)}</td>
                  <td>R$ ${r.advances.toFixed(2)}</td>
                  <td>R$ ${r.net.toFixed(2)}</td>
                </tr>
              `).join("")}

              <tr class="total">
                <td colspan="9">TOTAL — ${rows.length} funcionário(s)</td>
                <td>R$ ${T.gross.toFixed(2)}</td>
                <td>R$ ${T.vt.toFixed(2)}</td>
                <td>R$ ${T.vr.toFixed(2)}</td>
                <td>R$ ${T.advances.toFixed(2)}</td>
                <td>R$ ${T.net.toFixed(2)}</td>
              </tr>
            </tbody>
          </table>

          <div class="signatures">
            <div class="signature">
              Responsável RH: ${data.config.hrName || "_______________________"}
            </div>

            <div class="signature">
              Aprovado por
            </div>
          </div>

          <p style="margin-top:30px;">Data: ___/___/_____</p>

          <script>
            window.print();
          </script>
        </body>
      </html>
    `;

    const w = window.open("", "_blank");
    w.document.write(html);
    w.document.close();
  };

  const exportXLS = () => {
    const wb = XLSX.utils.book_new();

    const header = [
      "Funcionário",
      "Cargo",
      "Obra",
      "Pres.",
      "Meio Dia",
      "Faltas",
      "Sem Registro",
      "HE",
      "Diária",
      "Bruto",
      "VT",
      "VR",
      "Adiant.",
      "Líquido",
    ];

    const body = rows.map(r => [
      r.name,
      r.role || "",
      obraName(r.obra),
      r.presentes,
      r.meiodia,
      r.faltas,
      r.semRegistro,
      r.ot,
      r.dailyRate,
      r.gross,
      r.vt,
      r.vr,
      r.advances,
      r.net,
    ]);

    const ws = XLSX.utils.aoa_to_sheet([
      header,
      ...body,
      [
        "TOTAL",
        "",
        "",
        rows.reduce((s, r) => s + r.presentes, 0),
        rows.reduce((s, r) => s + r.meiodia, 0),
        rows.reduce((s, r) => s + r.faltas, 0),
        rows.reduce((s, r) => s + r.semRegistro, 0),
        rows.reduce((s, r) => s + r.ot, 0),
        "",
        T.gross,
        T.vt,
        T.vr,
        T.advances,
        T.net,
      ],
    ]);

    ws["!cols"] = [20, 15, 15, 8, 8, 8, 10, 6, 10, 12, 10, 10, 10, 12].map(w => ({ wch: w }));

    XLSX.utils.book_append_sheet(wb, ws, "Folha");
    XLSX.writeFile(wb, `arcd-folha-${year}-${String(month + 1).padStart(2, "0")}-Q${q}.xlsx`);

    showToast("Excel gerado!");
  };

  const buildText = () => [
    `FOLHA DE PAGAMENTO — ARCD OBRAS`,
    `${data.config.companyName || ""}`,
    `${periodLabel}`,
    ``,
    ...rows.map(r => `• ${r.name} (${obraName(r.obra)}): ${fmt(r.net)}`),
    ``,
    `TOTAL LÍQUIDO: ${fmt(T.net)}`,
    `${rows.length} funcionário(s)`,
    `Gerado em ${new Date().toLocaleDateString("pt-BR")}`,
  ].join("\n");

  const years = [];

  for (let i = now.getFullYear() - 1; i <= now.getFullYear() + 1; i++) {
    years.push({ v: String(i), l: String(i) });
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }} className="anim">
      <div>
        <h2 style={{ fontFamily: "'Bebas Neue'", fontSize: 28, letterSpacing: 2, color: C.yellow }}>
          Folha de Pagamento
        </h2>

        <p style={{ color: C.muted, fontSize: 13 }}>
          Cálculo automático quinzenal
        </p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Sel value={String(year)} onChange={v => setYear(Number(v))} options={years} />

        <Sel
          value={String(month)}
          onChange={v => setMonth(Number(v))}
          options={Array.from({ length: 12 }, (_, i) => ({ v: String(i), l: monthName(i) }))}
        />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Sel
          value={q}
          onChange={setQ}
          options={[
            { v: "1", l: "1ª Quinzena" },
            { v: "2", l: "2ª Quinzena" },
          ]}
        />

        <Sel
          value={filterObra}
          onChange={setFilterObra}
          options={[
            { v: "all", l: "Todas as obras" },
            ...data.obras.map(o => ({ v: o.id, l: o.name })),
          ]}
        />
      </div>

      <div
        style={{
          background: `linear-gradient(135deg, ${C.yellow}, ${C.yellowD})`,
          color: C.bg,
          padding: "18px 16px",
          border: `1px solid ${C.yellow}`,
        }}
      >
        <p
          style={{
            fontSize: 11,
            fontWeight: 800,
            letterSpacing: 1,
            textTransform: "uppercase",
            opacity: 0.8,
          }}
        >
          Total Líquido
        </p>

        <p style={{ fontFamily: "'Bebas Neue'", fontSize: 36, letterSpacing: 2 }}>
          {fmt(T.net)}
        </p>

        <p style={{ fontSize: 12, fontWeight: 600 }}>
          {rows.length} funcionário(s) · {periodLabel}
        </p>

        <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginTop: 8, fontSize: 12 }}>
          <span>Bruto: {fmt(T.gross)}</span>
          {T.vt > 0 && <span>VT: {fmt(T.vt)}</span>}
          {T.vr > 0 && <span>VR: {fmt(T.vr)}</span>}
          {T.advances > 0 && <span>Adiant.: -{fmt(T.advances)}</span>}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Btn onClick={printPDF} v="ghost">
          <Ic n="file" s={15} />
          PDF / Imprimir
        </Btn>

        <Btn onClick={exportXLS} v="success">
          <Ic n="download" s={15} />
          Excel .xlsx
        </Btn>

        <Btn
          onClick={() => window.open(`mailto:${data.config.hrEmail || ""}?subject=${encodeURIComponent("Folha - " + periodLabel)}&body=${encodeURIComponent(buildText())}`)}
          v="info"
        >
          <Ic n="mail" s={15} />
          E-mail
        </Btn>

        <Btn
          onClick={() => navigator.clipboard.writeText(buildText()).then(() => showToast("Copiado!")).catch(() => showToast("Erro ao copiar", "error"))}
          v="success"
        >
          <Ic n="copy" s={15} />
          WhatsApp
        </Btn>
      </div>

      {rows.length === 0 && (
        <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 20, textAlign: "center" }}>
          <p style={{ color: C.muted }}>Nenhum funcionário com movimentação nesta quinzena.</p>
        </div>
      )}

      {rows.map(r => (
        <div key={r.id}>
          <button
            onClick={() => setExpandedId(expandedId === r.id ? null : r.id)}
            style={{
              background: C.card,
              border: `1px solid ${C.border}`,
              padding: "13px 15px",
              width: "100%",
              cursor: "pointer",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              borderLeft: `4px solid ${C.yellow}`,
              color: C.text,
              textAlign: "left",
            }}
          >
            <div>
              <p style={{ fontFamily: "'Barlow Condensed'", fontWeight: 800, fontSize: 16 }}>
                {r.name}
              </p>

              <p style={{ fontSize: 12, color: C.muted }}>
                {obraName(r.obra)} · {r.presentes}P {r.meiodia}M {r.faltas}F {r.semRegistro}S/R{r.ot > 0 ? ` · ${r.ot}h` : ""}
              </p>
            </div>

            <div style={{ textAlign: "right" }}>
              <p style={{ fontFamily: "'Barlow Condensed'", fontWeight: 900, fontSize: 18, color: C.yellow }}>
                {fmt(r.net)}
              </p>

              {r.advances > 0 && (
                <p style={{ fontSize: 11, color: C.red }}>
                  -{fmt(r.advances)}
                </p>
              )}
            </div>
          </button>

          {expandedId === r.id && (
            <div
              style={{
                background: C.surface,
                border: `1px solid ${C.border}`,
                borderTop: 0,
                padding: 14,
              }}
            >
              <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginBottom: 12 }}>
                {[
                  ["Diária", fmt(r.dailyRate)],
                  ["Bruto", fmt(r.gross)],
                  ["VT+VR", fmt(r.vt + r.vr)],
                  ["Adiant.", fmt(r.advances), C.red],
                  ["Líquido", fmt(r.net), C.yellow],
                  ["HE", `${r.ot}h`],
                ].map(([l, v, c]) => (
                  <div key={l} style={{ background: C.card, padding: 8, border: `1px solid ${C.border}` }}>
                    <p style={{ fontSize: 10, color: C.muted, textTransform: "uppercase" }}>
                      {l}
                    </p>

                    <p style={{ fontWeight: 800, color: c || C.text }}>
                      {v}
                    </p>
                  </div>
                ))}
              </div>

              {r.pixKey && (
                <p style={{ fontSize: 12, color: C.subtle, marginBottom: 10 }}>
                  PIX: {r.pixKey}
                </p>
              )}

              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(42px, 1fr))", gap: 4 }}>
                {days.map(d => {
                  const a = getAtt(data, r.id, d);
                  const s = a?.status;
                  const col = s === "P" ? C.green : s === "M" ? C.yellow : s === "F" ? C.red : C.muted;

                  return (
                    <div
                      key={d}
                      style={{
                        background: C.card,
                        border: `1px solid ${C.border}`,
                        padding: 5,
                        textAlign: "center",
                      }}
                    >
                      <p style={{ fontSize: 9, color: C.muted }}>
                        {fmtDate(d)}
                      </p>

                      <p style={{ color: col, fontWeight: 900 }}>
                        {s || "–"}
                      </p>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// RELATÓRIOS
// ═══════════════════════════════════════════════════════════════════
function Relatorios({data}){
  const now=new Date();
  const [month,setMonth]=useState(now.getMonth());
  const [year]=useState(now.getFullYear());
  const allDays=getDays(year,month);
  const obraName=id=>data.obras.find(o=>o.id===id)?.name||"Sem obra";

  const empStats=data.employees.filter(e=>e.active!==false).map(e=>{
    const P=allDays.filter(d=>attStatus(data,e.id,d)==="P").length;
    const M=allDays.filter(d=>attStatus(data,e.id,d)==="M").length;
    const pct=allDays.length>0?Math.round(((P+M*.5)/allDays.length)*100):0;
    return{name:e.name,P,M,pct};
  }).sort((a,b)=>b.pct-a.pct);

  const obraStats=data.obras.map(o=>{
    const emps=data.employees.filter(e=>e.obra===o.id&&e.active!==false);
    let cost=0;
    emps.forEach(e=>allDays.forEach(d=>{const s=attStatus(data,e.id,d);if(s==="P")cost+=e.dailyRate||0;else if(s==="M")cost+=(e.dailyRate||0)*.5;}));
    return{name:o.name,cost,emps:emps.length};
  }).filter(o=>o.emps>0);

  const dailyTrend=allDays.slice(0,now.getDate()).map(d=>({
    d:fmtDate(d),
    P:data.employees.filter(e=>attStatus(data,e.id,d)==="P").length,
    M:data.employees.filter(e=>attStatus(data,e.id,d)==="M").length,
  }));

  let P_=0,M_=0,F_=0;
  data.employees.forEach(e=>allDays.forEach(d=>{const s=attStatus(data,e.id,d);if(s==="P")P_++;else if(s==="M")M_++;else if(s==="F")F_++;}));
  const pieData=[{name:"Presentes",value:P_},{name:"Meio Dia",value:M_},{name:"Faltas",value:F_}].filter(d=>d.value>0);

  return(
    <div style={{display:"flex",flexDirection:"column",gap:16}} className="anim">
      <div><h2 style={{fontFamily:"'Bebas Neue'",fontSize:28,letterSpacing:2,color:C.yellow}}>Relatórios</h2>
        <p style={{color:C.muted,fontSize:13}}>Análise de presença e custos</p></div>

      <Sel label="Mês" value={String(month)} onChange={v=>setMonth(Number(v))}
        options={Array.from({length:12},(_,i)=>({v:String(i),l:fullMonth(i)+" "+year}))}/>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        {[
          ["Total presenças",P_,C.green],
          ["Custo mensal",fmt(obraStats.reduce((s,o)=>s+o.cost,0)),C.yellow],
          ["Funcionários",data.employees.filter(e=>e.active!==false).length,C.blue],
          ["Obras ativas",data.obras.filter(o=>o.status==="active").length,C.orange],
        ].map(([l,v,c])=>(
          <div key={l} style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${c}`,padding:"13px"}}>
            <p style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>{l}</p>
            <p style={{fontSize:22,fontWeight:900,fontFamily:"'Bebas Neue'",color:c,marginTop:3,letterSpacing:1}}>{v}</p>
          </div>
        ))}
      </div>

      {dailyTrend.length>0&&(
        <div style={{background:C.card,border:`1px solid ${C.border}`,padding:"14px 14px 8px"}}>
          <p style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>Presença diária — {fullMonth(month)}</p>
          <ResponsiveContainer width="100%" height={120}>
            <LineChart data={dailyTrend}>
              <CartesianGrid strokeDasharray="3 3" stroke={C.border}/>
              <XAxis dataKey="d" tick={{fill:C.muted,fontSize:9}} axisLine={false} tickLine={false} interval="preserveStartEnd"/>
              <YAxis tick={{fill:C.muted,fontSize:9}} axisLine={false} tickLine={false} width={20}/>
              <Tooltip contentStyle={{background:C.surface,border:`1px solid ${C.border}`,fontSize:12}}/>
              <Line type="monotone" dataKey="P" name="Presentes" stroke={C.green} dot={false} strokeWidth={2}/>
              <Line type="monotone" dataKey="M" name="Meio Dia" stroke={C.yellow} dot={false} strokeWidth={2}/>
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {obraStats.length>0&&(
        <div style={{background:C.card,border:`1px solid ${C.border}`,padding:"14px 14px 8px"}}>
          <p style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>Custo por Obra — {fullMonth(month)}</p>
          <ResponsiveContainer width="100%" height={obraStats.length*44+30}>
            <BarChart data={obraStats} layout="vertical" barSize={18}>
              <XAxis type="number" tick={{fill:C.muted,fontSize:10}} axisLine={false} tickLine={false} tickFormatter={v=>`R$${(v/1000).toFixed(0)}k`}/>
              <YAxis type="category" dataKey="name" tick={{fill:C.subtle,fontSize:11}} axisLine={false} tickLine={false} width={80}/>
              <Tooltip contentStyle={{background:C.surface,border:`1px solid ${C.border}`,fontSize:12}} formatter={v=>[fmt(v),"Custo"]}/>
              <Bar dataKey="cost" radius={[0,4,4,0]}>{obraStats.map((_,i)=><Cell key={i} fill={CHART_COLORS[i%CHART_COLORS.length]}/>)}</Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {empStats.length>0&&(
        <div style={{background:C.card,border:`1px solid ${C.border}`,padding:14}}>
          <p style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>% Presença por Funcionário</p>
          {empStats.map(e=>(
            <div key={e.name} style={{marginBottom:10}}>
              <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}>
                <span style={{fontSize:13,fontWeight:600}}>{e.name}</span>
                <span style={{fontSize:13,fontWeight:700,color:e.pct>=80?C.green:e.pct>=50?C.yellow:C.red}}>{e.pct}%</span>
              </div>
              <div style={{height:5,background:C.border,overflow:"hidden"}}>
                <div style={{height:"100%",width:`${e.pct}%`,background:e.pct>=80?C.green:e.pct>=50?C.yellow:C.red,transition:"width .4s"}}/>
              </div>
            </div>
          ))}
        </div>
      )}

      {pieData.length>0&&(
        <div style={{background:C.card,border:`1px solid ${C.border}`,padding:"14px 14px 8px"}}>
          <p style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>Distribuição de Presença</p>
          <ResponsiveContainer width="100%" height={170}>
            <PieChart><Pie data={pieData} cx="50%" cy="50%" outerRadius={65} dataKey="value" label={({name,percent})=>`${name} ${(percent*100).toFixed(0)}%`} labelLine={false} fontSize={11}>
              {pieData.map((_,i)=><Cell key={i} fill={[C.green,C.yellow,C.red][i]}/>)}
            </Pie><Tooltip contentStyle={{background:C.surface,border:`1px solid ${C.border}`,fontSize:12}}/></PieChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* Histórico de Transferências e Demissões */}
      {(data.changeLog||[]).length>0&&(
        <div style={{background:C.card,border:`1px solid ${C.border}`,padding:14}}>
          <p style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>Histórico de Movimentações</p>
          {[...(data.changeLog||[])].reverse().slice(0,20).map(log=>(
            <div key={log.id} style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",padding:"8px 0",borderBottom:`1px solid ${C.border}`}}>
              <div style={{flex:1}}>
                <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:2}}>
                  {log.type==="transfer"
                    ?<Badge color={C.yellow}>↗ Transferência</Badge>
                    :<Badge color={C.red}>✕ Demissão</Badge>}
                  <span style={{fontSize:13,fontWeight:700}}>{log.empName}</span>
                </div>
                {log.type==="transfer"
                  ?<p style={{fontSize:11,color:C.muted}}>{log.from} → <b style={{color:C.yellow}}>{log.to}</b></p>
                  :<p style={{fontSize:11,color:C.muted}}>Desligado de {log.from}</p>}
              </div>
              <span style={{fontSize:11,color:C.muted,marginLeft:8,flexShrink:0}}>{fmtDate(log.date)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// CONFIG
// ═══════════════════════════════════════════════════════════════════
function Config({data,update,showToast,onLogout}){
  const [form,setForm]=useState(data.config||{});
  const F=k=>v=>setForm(f=>({...f,[k]:v}));
  const save=()=>{update({...data,config:form});showToast("Configurações salvas!");};

  const exportBackup=()=>{
    const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");a.href=url;a.download=`arced-backup-${today()}.json`;a.click();
    URL.revokeObjectURL(url);showToast("Backup exportado!");
  };
  const importRef=useRef();
  const importBackup=e=>{
    const file=e.target.files[0];if(!file)return;
    const reader=new FileReader();
    reader.onload=ev=>{try{update(JSON.parse(ev.target.result));showToast("Backup restaurado!");}catch{showToast("Arquivo inválido","error");}};
    reader.readAsText(file);e.target.value="";
  };

  return(
    <div style={{display:"flex",flexDirection:"column",gap:14}} className="anim">
      <div><h2 style={{fontFamily:"'Bebas Neue'",fontSize:28,letterSpacing:2,color:C.yellow}}>Configurações</h2>
        <p style={{color:C.muted,fontSize:13}}>Empresa, RH e segurança</p></div>

      <div style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${C.yellow}`,padding:16}}>
        <p style={{fontSize:11,fontWeight:700,color:C.yellow,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>Dados da Empresa</p>
        <div style={{display:"flex",flexDirection:"column",gap:12}}>
          <Inp label="Nome da Empresa" value={form.companyName} onChange={F("companyName")} placeholder="ArcD Construtora"/>
          <Inp label="CNPJ" value={form.cnpj} onChange={F("cnpj")} placeholder="00.000.000/0001-00"/>
        </div>
      </div>

      <div style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${C.blue}`,padding:16}}>
        <p style={{fontSize:11,fontWeight:700,color:C.blue,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>Contato do RH</p>
        <div style={{display:"flex",flexDirection:"column",gap:12}}>
          <Inp label="Nome do responsável" value={form.hrName} onChange={F("hrName")} placeholder="Maria Silva"/>
          <Inp label="E-mail do RH" type="email" value={form.hrEmail} onChange={F("hrEmail")} placeholder="rh@arced.com.br"/>
        </div>
        {form.hrEmail&&<p style={{fontSize:12,color:C.subtle,marginTop:8}}>✅ Folhas serão enviadas para <b>{form.hrEmail}</b></p>}
      </div>

      <Btn onClick={save} size="lg" full><Ic n="check" s={18}/>Salvar Configurações</Btn>

      <div style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${C.yellow}`,padding:16}}>
        <p style={{fontSize:11,fontWeight:700,color:C.yellow,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>Sessão</p>
        <div style={{background:C.surface,border:`1px solid ${C.border}`,padding:"12px 14px",marginBottom:10,display:"flex",alignItems:"center",gap:10}}>
          <Ic n="users" s={18} style={{color:C.yellow}}/>
          <div>
            <p style={{fontSize:12,color:C.muted}}>Conectado como</p>
            <p style={{fontSize:15,fontWeight:700,color:C.text}}>{data.userName||"Usuário"}</p>
          </div>
        </div>
        <Btn onClick={onLogout} v="ghost" full><Ic n="logout" s={16}/>Trocar de Usuário</Btn>
      </div>

      <div style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${C.yellow}`,padding:16}}>
        <p style={{fontSize:11,fontWeight:700,color:C.yellow,textTransform:"uppercase",letterSpacing:.7,marginBottom:12}}>Backup de Dados</p>
        <div style={{display:"flex",flexDirection:"column",gap:10}}>
          <Btn onClick={exportBackup} v="warning" full><Ic n="backup" s={16}/>Exportar Backup JSON</Btn>
          <input type="file" accept=".json" ref={importRef} onChange={importBackup} style={{display:"none"}}/>
          <Btn onClick={()=>importRef.current.click()} v="ghost" full><Ic n="upload" s={16}/>Importar Backup</Btn>
        </div>
        <p style={{fontSize:11,color:C.muted,marginTop:10}}>⚠️ Importar substitui todos os dados atuais.</p>
      </div>

      <div style={{background:C.card,border:`1px solid ${C.border}`,padding:16}}>
        <p style={{fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:.7,marginBottom:10}}>Estatísticas</p>
        {[["Obras",data.obras.length],["Funcionários ativos",data.employees.filter(e=>e.active!==false).length],["Registros de ponto",Object.values(data.attendance).reduce((s,v)=>s+Object.keys(v).length,0)],["Adiantamentos",(data.advances||[]).length]].map(([l,v])=>(
          <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"7px 0",borderBottom:`1px solid ${C.border}`}}>
            <span style={{fontSize:13,color:C.subtle}}>{l}</span>
            <span style={{fontSize:13,fontWeight:700,color:C.yellow}}>{v}</span>
          </div>
        ))}
      </div>

    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// DAILY CHECK MODAL
// ═══════════════════════════════════════════════════════════════════
function DailyCheckModal({data,update,showToast,onClose}) {
  const [empStatus, setEmpStatus] = useState({});
  const [empNewObra, setEmpNewObra] = useState({});
  const [empEndDate, setEmpEndDate] = useState({});

  const activeEmps = (data.employees || []).filter(e => e.active !== false);
  const activeObras = (data.obras || []).filter(o => o.status !== "done");

  const obraName = id => data.obras.find(o => o.id === id)?.name || "—";
  const getStatus = id => empStatus[id] || "same";

  const setStatus = (id, status) => {
    setEmpStatus(prev => ({ ...prev, [id]: status }));
  };

  const confirmAllSame = () => {
    update({
      ...data,
      dailyCheckDate: today(),
      changeLog: [
        ...(data.changeLog || []),
        {
          id: uid(),
          date: today(),
          type: "daily_check",
          message: "Verificação diária concluída: todos continuam nas mesmas obras.",
        },
      ],
    });

    showToast("Verificação diária concluída!");
    onClose();
  };

  const confirmChanges = () => {
    const transferWithoutObra = activeEmps.find(e =>
      getStatus(e.id) === "transfer" && !empNewObra[e.id]
    );

    if (transferWithoutObra) {
      showToast(`Selecione a nova obra de ${transferWithoutObra.name}`, "error");
      return;
    }

    let changes = 0;
    const changeLog = [...(data.changeLog || [])];

    const employees = data.employees.map(emp => {
      const status = getStatus(emp.id);

      if (status === "transfer") {
        const newObra = empNewObra[emp.id];
        const from = obraName(emp.obra);
        const to = obraName(newObra);

        changes++;

        changeLog.push({
          id: uid(),
          date: today(),
          empId: emp.id,
          empName: emp.name,
          type: "transfer",
          from,
          to,
          message: `${emp.name} transferido de ${from} para ${to}`,
        });

        return {
          ...emp,
          obra: newObra,
          lastObra: emp.obra,
          active: true,
          endDate: "",
          terminationReason: "",
        };
      }

      if (status === "fired") {
        const endDate = empEndDate[emp.id] || today();
        const from = obraName(emp.obra);

        changes++;

        changeLog.push({
          id: uid(),
          date: endDate,
          empId: emp.id,
          empName: emp.name,
          type: "dismissal",
          from,
          message: `${emp.name} demitido/inativado em ${endDate}`,
        });

        return {
          ...emp,
          active: false,
          endDate,
          terminationReason: "Demitido",
          lastObra: emp.obra,
        };
      }

      return emp;
    });

    update({
      ...data,
      employees,
      changeLog,
      dailyCheckDate: today(),
    });

    showToast(
      changes > 0
        ? `${changes} alteração${changes > 1 ? "es" : ""} aplicada${changes > 1 ? "s" : ""}!`
        : "Verificação diária concluída!"
    );

    onClose();
  };

  return (
   <Modal
  title="Transferência / Demissão de Trabalhador"
  wide
  onClose={onClose}
>
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        <div style={{
          background: C.yellow + "14",
          border: `1px solid ${C.yellow}55`,
          borderLeft: `4px solid ${C.yellow}`,
          padding: "12px 14px",
        }}>
          <p style={{
            color: C.yellow,
            fontFamily: "'Barlow Condensed'",
            fontWeight: 800,
            fontSize: 16,
            letterSpacing: .5,
            textTransform: "uppercase",
          }}>
            Antes de lançar o ponto, confirme a situação de cada trabalhador.
          </p>

          <p style={{ color: C.subtle, fontSize: 12, marginTop: 4 }}>
            Informe se permaneceu na mesma obra, se foi transferido ou se foi demitido/inativado.
          </p>
        </div>

        {activeEmps.length === 0 && (
          <p style={{ color: C.muted, fontSize: 13 }}>
            Nenhum funcionário ativo para verificar.
          </p>
        )}

        {activeEmps.map(emp => {
          const status = getStatus(emp.id);

          return (
            <div
              key={emp.id}
              style={{
                background: C.card,
                border: `1px solid ${C.border}`,
                borderLeft: `4px solid ${
                  status === "same" ? C.green :
                  status === "transfer" ? C.yellow :
                  C.red
                }`,
                padding: 12,
                display: "flex",
                flexDirection: "column",
                gap: 10,
              }}
            >
              <div>
                <p style={{
                  fontFamily: "'Barlow Condensed'",
                  fontWeight: 800,
                  fontSize: 17,
                  color: C.text,
                }}>
                  {emp.name}
                </p>

                <p style={{ fontSize: 12, color: C.muted }}>
                  Obra atual: {obraName(emp.obra)}
                  {emp.role ? ` · ${emp.role}` : ""}
                </p>
              </div>

              <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 6 }}>
                <Btn
                  v={status === "same" ? "success" : "ghost"}
                  size="sm"
                  onClick={() => setStatus(emp.id, "same")}
                >
                  Mesma obra
                </Btn>

                <Btn
                  v={status === "transfer" ? "warning" : "ghost"}
                  size="sm"
                  onClick={() => setStatus(emp.id, "transfer")}
                >
                  Transferido
                </Btn>

                <Btn
                  v={status === "fired" ? "danger" : "ghost"}
                  size="sm"
                  onClick={() => setStatus(emp.id, "fired")}
                >
                  Demitido
                </Btn>
              </div>

              {status === "transfer" && (
                <Sel
                  label="Nova obra *"
                  value={empNewObra[emp.id] || ""}
                  onChange={v => setEmpNewObra(prev => ({ ...prev, [emp.id]: v }))}
                  options={[
                    { v: "", l: "Selecione a nova obra" },
                    ...activeObras
                      .filter(o => o.id !== emp.obra)
                      .map(o => ({ v: o.id, l: o.name })),
                  ]}
                />
              )}

              {status === "fired" && (
                <Inp
                  label="Data de término *"
                  type="date"
                  value={empEndDate[emp.id] || today()}
                  onChange={v => setEmpEndDate(prev => ({ ...prev, [emp.id]: v }))}
                />
              )}
            </div>
          );
        })}

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginTop: 4 }}>
          <Btn v="ghost" onClick={confirmAllSame} full>
            Todos continuam iguais
          </Btn>

          <Btn onClick={confirmChanges} full>
            <Ic n="check" s={16} />
            Confirmar verificação
          </Btn>
        </div>
      </div>
    </Modal>
  );
}

// ═══════════════════════════════════════════════════════════════════
// AI ASSISTANT
// ═══════════════════════════════════════════════════════════════════
function AIAssistant({data,onClose}){
  const [msgs,setMsgs]=useState([{role:"assistant",content:"Olá! Sou o assistente IA da ArcD. Posso analisar sua equipe, custos, presenças e responder dúvidas sobre o sistema. Como posso ajudar? 🏗️"}]);
  const [input,setInput]=useState("");
  const [loading,setLoading]=useState(false);
  const bottomRef=useRef();
  const obraName=id=>data.obras.find(o=>o.id===id)?.name||"—";

  useEffect(()=>{bottomRef.current?.scrollIntoView({behavior:"smooth"});},[msgs]);

  const sendMsg=async()=>{
    const q=input.trim();if(!q||loading)return;
    setInput("");
    const newMsgs=[...msgs,{role:"user",content:q}];
    setMsgs(newMsgs);setLoading(true);
    const now=new Date();const t=today();
    const system=`Você é o assistente de RH inteligente da construtora ArcD. Analise os dados abaixo e responda de forma útil e concisa em português.
Empresa: ${data.config.companyName||"ArcD"}
Hoje: ${t} | Obras: ${data.obras.map(o=>o.name).join(", ")}
Funcionários (${data.employees.length}): ${JSON.stringify(data.employees.map(e=>({nome:e.name,cargo:e.role,obra:obraName(e.obra),diaria:e.dailyRate,hoje:attStatus(data,e.id,t)||"sem registro"})))}
Custo quinzena: ${(()=>{const {q1,q2}=getQ(now.getFullYear(),now.getMonth());const days=now.getDate()<=15?q1:q2;let c=0;data.employees.forEach(e=>days.forEach(d=>{const s=attStatus(data,e.id,d);if(s==="P")c+=e.dailyRate||0;else if(s==="M")c+=(e.dailyRate||0)*.5;}));return c.toFixed(2);})()}
Adiantamentos este mês: ${(data.advances||[]).filter(a=>new Date(a.date).getMonth()===now.getMonth()).reduce((s,a)=>s+(a.amount||0),0).toFixed(2)}
Responda em português, seja direto e use dados reais do sistema quando possível.`;
    try{
      const res=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:1000,system,messages:newMsgs.map(m=>({role:m.role,content:m.content}))})});
      const d=await res.json();
      setMsgs(m=>[...m,{role:"assistant",content:d.content?.[0]?.text||"Erro na resposta."}]);
    }catch{setMsgs(m=>[...m,{role:"assistant",content:"Erro de conexão. Tente novamente."}]);}
    finally{setLoading(false);}
  };

  const SUGG=["Quem faltou hoje?","Qual obra tem maior custo?","Funcionários com mais faltas este mês?","Qual o total a pagar nessa quinzena?"];

  return(
    <div style={{position:"fixed",inset:0,background:"#000c",zIndex:300,display:"flex",alignItems:"flex-end",justifyContent:"center"}}>
      <div style={{background:C.card,borderRadius:0,width:"100%",maxWidth:480,height:"82vh",display:"flex",flexDirection:"column",borderTop:`3px solid ${C.yellow}`}}>
        <div style={{padding:"14px 18px",borderBottom:`1px solid ${C.border}`,display:"flex",justifyContent:"space-between",alignItems:"center",background:C.surface}}>
          <div style={{display:"flex",alignItems:"center",gap:12}}>
            <div style={{background:C.yellow,padding:"5px 7px",display:"flex"}}>
              <Ic n="bot" s={18} style={{color:C.bg}}/>
            </div>
            <div>
              <p style={{fontFamily:"'Bebas Neue'",fontSize:18,color:C.yellow,letterSpacing:2}}>ASSISTENTE IA</p>
              <p style={{fontSize:10,color:C.muted}}>ArcD · Powered by Claude</p>
            </div>
          </div>
          <button onClick={onClose} style={{background:"none",border:"none",color:C.muted,cursor:"pointer"}}><Ic n="x" s={20}/></button>
        </div>

        <div style={{flex:1,overflowY:"auto",padding:"14px 16px",display:"flex",flexDirection:"column",gap:12}}>
          {msgs.map((m,i)=>(
            <div key={i} style={{display:"flex",justifyContent:m.role==="user"?"flex-end":"flex-start"}}>
              <div style={{
                maxWidth:"86%",padding:"10px 14px",
                background:m.role==="user"?C.yellow:C.surface,
                color:m.role==="user"?C.bg:C.text,
                fontSize:14,lineHeight:1.5,
                border:m.role==="assistant"?`1px solid ${C.border}`:"none",
              }}>
                {m.content}
              </div>
            </div>
          ))}
          {loading&&(
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <div style={{background:C.surface,border:`1px solid ${C.border}`,padding:"10px 14px",display:"flex",gap:8,alignItems:"center"}}>
                <Spinner small/><span style={{fontSize:13,color:C.muted}}>Analisando dados...</span>
              </div>
            </div>
          )}
          <div ref={bottomRef}/>
        </div>

        {msgs.length<=1&&(
          <div style={{padding:"0 14px 10px",display:"flex",flexWrap:"wrap",gap:6}}>
            {SUGG.map(s=>(
              <button key={s} onClick={()=>setInput(s)} style={{background:C.surface,border:`1px solid ${C.yellow}33`,padding:"5px 12px",fontSize:12,color:C.subtle,cursor:"pointer",fontFamily:"'Barlow'"}}>
                {s}
              </button>
            ))}
          </div>
        )}

        <div style={{padding:"10px 14px",borderTop:`1px solid ${C.border}`,display:"flex",gap:8,background:C.surface}}>
          <input value={input} onChange={e=>setInput(e.target.value)}
            onKeyDown={e=>e.key==="Enter"&&!e.shiftKey&&sendMsg()}
            placeholder="Pergunte sobre sua equipe..."
            style={{...inputStyle,flex:1}}
            onFocus={e=>e.target.style.borderColor=C.yellow}
            onBlur={e=>e.target.style.borderColor=C.border}/>
          <Btn onClick={sendMsg} disabled={!input.trim()||loading}><Ic n="send" s={16}/></Btn>
        </div>
      </div>
    </div>
  );
}
